string get_antonym(string word) {
  // Open the WordNet database.
  ifstream wordnet("wordnet.dat");

  // Check if the database is open.
  if (!wordnet.is_open()) {
    cout << "Error opening WordNet database." << endl;
    return "";
  }

  // Get the list of synsets for the given word.
  vector<string> synsets;
  while (wordnet >> word) {
    if (word == "synset") {
      string synset_id;
      wordnet >> synset_id;
      synsets.push_back(synset_id);
    }
  }

  // Check if the word has an antonym.
  if (synsets.empty()) {
    return "";
  }

  // Get the antonym of the given word.
  string antonym;
  wordnet >> antonym;

  // Close the WordNet database.
  wordnet.close();

  return antonym;
}

int main() {
  // Get the word from the user.
  cout << "Enter a word: ";
  string word;
  cin >> word;

  // Find the antonym of the given word.
  string antonym = get_antonym(word);

  // Print the antonym of the given word.
  cout << "The antonym of " << word << " is " << antonym << endl;

